func init() {
	rt.RegisterErrorClassifier(func(err error) (rt.Kind, string, bool) {
		if go2.IsMissingKind(err) {
			return rt.FailureKind, "MissingKind: " + err.Error(), true
		}
		if go2.IsMissingVersion(err) {
			return rt.FailureKind, "MissingVersion: " + err.Error(), true
		}
		if go2.IsNotRegisteredError(err) {
			return rt.FailureKind, "NotRegisteredError: " + err.Error(), true
		}
		if go2.IsStrictDecodingError(err) {
			return rt.FailureKind, "StrictDecodingError: " + err.Error(), true
		}
		return rt.FailureKind, "", false
	})
}
